from common import *
GFE = ("<h2>What Therapy Costs, and Your Rights on Price</h2>\n<p>Session fees vary by region and by the therapist's licence. Before you book:</p>\n" + ul([
 "<strong>With insurance:</strong> mental health care must be covered no more restrictively than medical care under federal parity law. Check your copay or coinsurance, your deductible, and whether the therapist is in network.",
 "<strong>Paying yourself:</strong> under the No Surprises Act you're entitled to a written Good Faith Estimate if you schedule at least 3 business days ahead or ask for one. If the bill comes in at least $400 above the estimate, you can dispute it within 120 days.",
 "<strong>Lower-cost options:</strong> community mental health centers, university training clinics, employee assistance programs (often several free sessions) and sliding-scale practices.",
]))
